<?php require_once 'config.php';require_login();$page_title='Laporan';$page_desc='Rekapitulasi data kependudukan.';$total=$pdo->query('SELECT COUNT(*) FROM warga')->fetchColumn();$laki=$pdo->query("SELECT COUNT(*) FROM warga WHERE jk='L'")->fetchColumn();$perempuan=$pdo->query("SELECT COUNT(*) FROM warga WHERE jk='P'")->fetchColumn();$jobs=$pdo->query('SELECT pekerjaan,COUNT(*) jumlah FROM warga GROUP BY pekerjaan ORDER BY jumlah DESC')->fetchAll();$rows=$pdo->query('SELECT * FROM warga ORDER BY nama')->fetchAll();require 'partials/header.php';?><div class="cards"><div class="stat"><div class="icon blue">👥</div><div><span>Total Jiwa</span><strong><?=$total?></strong></div></div><div class="stat"><div class="icon green">♂</div><div><span>Laki-laki</span><strong><?=$laki?></strong></div></div><div class="stat"><div class="icon pink">♀</div><div><span>Perempuan</span><strong><?=$perempuan?></strong></div></div></div><section class="panel"><div class="panel-head"><h3>Rekap Pekerjaan</h3><button class="btn primary" onclick="window.print()">🖨️ Cetak / Simpan PDF</button></div><div class="table-wrap"><table><thead><tr><th>No</th><th>Pekerjaan</th><th>Jumlah</th></tr></thead><tbody><?php foreach($jobs as $i=>$j): ?><tr><td><?=$i+1?></td><td><?=e($j['pekerjaan'])?></td><td><?=$j['jumlah']?> orang</td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><div class="panel-head"><h3>Rekap Data Warga</h3></div><div class="table-wrap"><table><thead><tr><th>No</th><th>Nama</th><th>JK</th><th>Alamat</th><th>Pekerjaan</th></tr></thead><tbody><?php foreach($rows as $i=>$x): ?><tr><td><?=$i+1?></td><td><?=e($x['nama'])?></td><td><?=e($x['jk'])?></td><td><?=e($x['alamat'])?></td><td><?=e($x['pekerjaan'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php require 'partials/footer.php';?>
